UPDATE sys_dictionary
label = #{label.value}, enabled = #{enabled.value}, sort_order = #{sortOrder.value}, version = version + 1
WHERE dictionary_key = #{key} AND version = #{version}

UPDATE sys_dictionary_option
label = #{label.value}, i18n = #{i18n.value,jdbcType=OTHER}, enabled = #{enabled.value}, sort_order = #{sortOrder.value}, version = version + 1
WHERE dictionary_key = #{key} AND option_value = #{value} AND version = #{version}
